DROP TABLE IF EXISTS `click_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `click_events` (
  `id` int NOT NULL AUTO_INCREMENT,
  `session_id` varchar(100) NOT NULL,
  `user_id` int DEFAULT NULL,
  `page_url` varchar(500) NOT NULL,
  `element_type` varchar(50) DEFAULT NULL,
  `element_id` varchar(100) DEFAULT NULL,
  `element_class` varchar(200) DEFAULT NULL,
  `element_text` varchar(500) DEFAULT NULL,
  `click_x` int DEFAULT NULL,
  `click_y` int DEFAULT NULL,
  `timestamp` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_session` (`session_id`),
  KEY `idx_timestamp` (`timestamp`)
) ENGINE=InnoDB AUTO_INCREMENT=9893 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
