--
-- Table structure for table `product_feature_cards`
--

DROP TABLE IF EXISTS `product_feature_cards`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_feature_cards` (
  `id` int NOT NULL AUTO_INCREMENT,
  `product_id` int NOT NULL COMMENT 'Links to products.id - NO field needed in products table',
  `card_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Text displayed on the card (e.g., "Supports Hormonal Balance")',
  `card_image_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Image URL for the card icon/thumbnail (e.g., https://example.com/icons/hormonal-balance.png)',
  `display_order` int NOT NULL DEFAULT '0' COMMENT 'Order in which card should be displayed (1, 2, 3, 4)',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Whether this card is active/visible (1 = active, 0 = hidden)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_product_id` (`product_id`),
  KEY `idx_display_order` (`product_id`,`display_order`),
  CONSTRAINT `fk_product_feature_cards_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `product_feature_cards`
--

LOCK TABLES `product_feature_cards` WRITE;
/*!40000 ALTER TABLE `product_feature_cards` DISABLE KEYS */;
