--
-- Temporary view structure for view `recent_revenue_trends`
--

DROP TABLE IF EXISTS `recent_revenue_trends`;
/*!50001 DROP VIEW IF EXISTS `recent_revenue_trends`*/;
SET @saved_cs_client     = @@character_set_client;
/*!50503 SET character_set_client = utf8mb4 */;
/*!50001 CREATE VIEW `recent_revenue_trends` AS SELECT 
 1 AS `date`,
 1 AS `total_revenue`,
 1 AS `total_orders`,
 1 AS `unique_customers`,
 1 AS `average_order_value`,
 1 AS `revenue_growth_percent`,
 1 AS `orders_growth_percent`*/;
SET character_set_client = @saved_cs_client;

