--
-- Table structure for table `user_actions`
--

DROP TABLE IF EXISTS `user_actions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_actions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `session_id` varchar(100) NOT NULL,
  `user_id` int DEFAULT NULL,
  `actor_type` enum('customer','admin','guest') NOT NULL DEFAULT 'customer',
  `action_type` varchar(50) NOT NULL,
  `action_details` json DEFAULT NULL,
  `page_url` varchar(500) NOT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` varchar(500) DEFAULT NULL,
  `resource_type` varchar(50) DEFAULT NULL,
  `resource_id` int DEFAULT NULL,
  `user_session_id` int unsigned DEFAULT NULL,
  `timestamp` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_session` (`session_id`),
  KEY `idx_action` (`action_type`),
  KEY `idx_timestamp` (`timestamp`),
  KEY `idx_user_actions_user` (`user_id`,`actor_type`),
  KEY `idx_user_actions_type` (`action_type`),
  KEY `idx_user_actions_timestamp` (`timestamp`),
  KEY `idx_user_actions_session` (`user_session_id`),
  KEY `idx_user_actions_resource` (`resource_type`,`resource_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5677 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

